(function(){
  'use strict';
  const form=document.querySelector('[data-qr-form],[data-styled-form]');
  if(!form)return;
  const tool=form.dataset.tool||'logo';
  const lang=(document.documentElement.lang||'en').toLowerCase();
  const T={
    en:{ready:'Required information ready',left:'Still needed',good:'Looks good',required:'This field is required',content:'Enter text or a URL.',ssid:'Use a Wi‑Fi name from 1 to 32 bytes',wpa:'WPA password must be 8–63 characters',wep:'WEP password must be 5/13 ASCII or 10/26 hexadecimal characters',cc:'Use 212 or +212 — the + is added automatically',waPhone:'Use a valid international number; total must be 7–15 digits',phone:'Use 6–15 digits, with country code when needed',email:'Enter a valid email address',url:'Enter a full http(s) URL',google:'Use a valid Google review link',name:'Enter at least 2 characters',lat:'Latitude must be between -90 and 90',lng:'Longitude must be between -180 and 180',start:'Choose a valid start date and time',end:'End must be after the start time',optional:'Optional',short:'Use at least 2 characters',mapSource:'Google Maps link or coordinates',complete:'Everything required is ready — your QR can be generated.'},
    fr:{ready:'Informations requises prêtes',left:'À compléter',good:'Champ valide',required:'Ce champ est obligatoire',content:'Saisissez du texte ou une URL.',ssid:'Le nom Wi‑Fi doit contenir de 1 à 32 octets',wpa:'Le mot de passe WPA doit contenir 8 à 63 caractères',wep:'WEP : 5/13 caractères ASCII ou 10/26 caractères hexadécimaux',cc:'Utilisez 212 ou +212 — le + est ajouté automatiquement',waPhone:'Numéro international valide : 7 à 15 chiffres au total',phone:'Utilisez 6 à 15 chiffres, avec indicatif si nécessaire',email:'Saisissez une adresse e-mail valide',url:'Saisissez une URL http(s) complète',google:'Utilisez un lien valide vers un avis Google',name:'Saisissez au moins 2 caractères',lat:'Latitude entre -90 et 90',lng:'Longitude entre -180 et 180',start:'Choisissez une date et heure de début valides',end:'La fin doit être après le début',optional:'Facultatif',short:'Utilisez au moins 2 caractères',mapSource:'Lien Google Maps ou coordonnées',complete:'Toutes les informations requises sont prêtes.'},
    es:{ready:'Información requerida lista',left:'Falta',good:'Correcto',required:'Este campo es obligatorio',content:'Escribe texto o una URL.',ssid:'El nombre Wi‑Fi debe tener entre 1 y 32 bytes',wpa:'La contraseña WPA debe tener 8–63 caracteres',wep:'WEP: 5/13 caracteres ASCII o 10/26 hexadecimales',cc:'Usa 212 o +212 — el + se añade automáticamente',waPhone:'Número internacional válido: 7–15 dígitos en total',phone:'Usa 6–15 dígitos, con prefijo cuando sea necesario',email:'Introduce un email válido',url:'Introduce una URL http(s) completa',google:'Usa un enlace válido de reseña de Google',name:'Escribe al menos 2 caracteres',lat:'Latitud entre -90 y 90',lng:'Longitud entre -180 y 180',start:'Elige fecha y hora de inicio válidas',end:'El final debe ser posterior al inicio',optional:'Opcional',short:'Usa al menos 2 caracteres',mapSource:'Enlace de Google Maps o coordenadas',complete:'Toda la información requerida está lista.'},
    'pt-br':{ready:'Informações obrigatórias prontas',left:'Ainda falta',good:'Tudo certo',required:'Este campo é obrigatório',content:'Digite texto ou uma URL.',ssid:'O nome do Wi‑Fi deve ter de 1 a 32 bytes',wpa:'A senha WPA deve ter 8–63 caracteres',wep:'WEP: 5/13 caracteres ASCII ou 10/26 hexadecimais',cc:'Use 212 ou +212 — o + é adicionado automaticamente',waPhone:'Número internacional válido: 7–15 dígitos no total',phone:'Use 6–15 dígitos, com código do país quando necessário',email:'Digite um e-mail válido',url:'Digite uma URL http(s) completa',google:'Use um link válido de avaliação do Google',name:'Digite pelo menos 2 caracteres',lat:'Latitude entre -90 e 90',lng:'Longitude entre -180 e 180',start:'Escolha data e hora inicial válidas',end:'O fim deve ser depois do início',optional:'Opcional',short:'Use pelo menos 2 caracteres',mapSource:'Link do Google Maps ou coordenadas',complete:'Todas as informações obrigatórias estão prontas.'},
    ar:{ready:'المعلومات المطلوبة جاهزة',left:'باقي عليك',good:'ممتاز، الحقل صحيح',required:'هذا الحقل مطلوب',content:'أدخل نصاً أو رابطاً.',ssid:'اسم الشبكة من 1 إلى 32 بايت',wpa:'كلمة مرور WPA يجب أن تكون بين 8 و63 حرفاً',wep:'WEP: ‏5/13 حرفاً أو 10/26 رمزاً سداسياً',cc:'اكتب 212 أو +212 — ستتم إضافة + تلقائياً',waPhone:'رقم دولي صحيح: المجموع من 7 إلى 15 رقماً',phone:'استعمل من 6 إلى 15 رقماً مع رمز الدولة عند الحاجة',email:'أدخل بريداً إلكترونياً صحيحاً',url:'أدخل رابط http(s) كاملاً',google:'أدخل رابط تقييم Google صحيحاً',name:'أدخل حرفين على الأقل',lat:'خط العرض يجب أن يكون بين -90 و90',lng:'خط الطول يجب أن يكون بين -180 و180',start:'اختر تاريخ ووقت بداية صحيحين',end:'وقت النهاية يجب أن يكون بعد البداية',optional:'اختياري',short:'أدخل حرفين على الأقل',mapSource:'رابط Google Maps أو الإحداثيات',complete:'كل المعلومات المطلوبة جاهزة — يمكنك استعمال QR الآن.'}
  }[lang]||null;
  const t=T||{};
  const $=n=>form.elements[n];
  const v=n=>$(n)?String($(n).value||'').trim():'';
  const digits=s=>String(s||'').replace(/\D/g,'');
  const normalizeCountryCode=s=>{const d=digits(s);return d?`+${d}`:'';};
  const normalizeWhatsAppNumber=(cc,local)=>{const ccDigits=digits(cc),raw=String(local||'').trim();let localDigits=digits(raw);if(raw.startsWith('+'))return localDigits;if(ccDigits&&localDigits.startsWith(ccDigits)&&localDigits.length>=7)return localDigits;localDigits=localDigits.replace(/^0+/,'');return ccDigits+localDigits;};
  const utf8len=s=>new TextEncoder().encode(String(s||'')).length;
  const validURL=s=>{try{const u=new URL(s);return /^https?:$/.test(u.protocol);}catch{return false;}};
  const validGoogle=s=>{if(!validURL(s))return false;const h=new URL(s).hostname.toLowerCase();return h==='google.com'||h.endsWith('.google.com')||h.startsWith('google.')||h.includes('.google.')||h==='g.page'||h.endsWith('.g.page')||h==='goo.gl'||h.endsWith('.goo.gl')||h==='maps.app.goo.gl';};
  const ignored=new Set(['foreground','background','size','margin','error_level','dot_style','corner_style','frame_style','frame_text','frame_color','frame_text_color','frame_text_outline_width','frame_text_outline_color','center_icon','logo_size','hidden']);
  const touched=new WeakSet();
  const contentControls=[...form.querySelectorAll('input[name],textarea[name],select[name]')].filter(el=>!ignored.has(el.name)&&el.type!=='file');

  function rule(el){
    const n=el.name,s=String(el.value||'').trim(),required=el.required;
    if(n==='content'){const max=el.maxLength>0?el.maxLength:2000;return {ok:s.length>0&&s.length<=max,msg:s?t.content:t.required,hint:t.content,required:true};}
    if(n==='ssid')return {ok:utf8len(s)>=1&&utf8len(s)<=32,msg:s?t.ssid:t.required,hint:t.ssid,required:true};
    if(n==='password'){
      const sec=v('security')||'WPA';if(sec==='nopass')return {ok:true,msg:t.good,hint:t.optional,required:false,skip:true};
      if(!s)return {ok:false,msg:t.required,hint:sec==='WEP'?t.wep:t.wpa,required:true};
      const ok=sec==='WEP'?(/^([\x20-\x7E]{5}|[\x20-\x7E]{13})$/.test(s)||/^(?:[A-Fa-f0-9]{10}|[A-Fa-f0-9]{26})$/.test(s)):s.length>=8&&s.length<=63;
      return {ok,msg:sec==='WEP'?t.wep:t.wpa,hint:sec==='WEP'?t.wep:t.wpa,required:true};
    }
    if(n==='country_code')return {ok:/^\+?\d{1,4}$/.test(s),msg:s?t.cc:t.required,hint:t.cc,required:true};
    if(tool==='whatsapp'&&n==='phone'){
      const normalized=normalizeWhatsAppNumber(v('country_code'),s),ok=digits(s).length>=4&&normalized.length>=7&&normalized.length<=15;return {ok,msg:s?t.waPhone:t.required,hint:t.waPhone,required:true};
    }
    if(n==='phone'){
      if(!s&&!required)return {ok:true,msg:t.optional,hint:t.phone,required:false,skip:true};
      const d=digits(s).length;return {ok:d>=6&&d<=15,msg:s?t.phone:t.required,hint:t.phone,required};
    }
    if(n==='email'){
      if(!s&&!required)return {ok:true,msg:t.optional,hint:t.email,required:false,skip:true};
      return {ok:el.validity.valid&&s.length<=254,msg:s?t.email:t.required,hint:t.email,required};
    }
    if(n==='website'){
      if(!s)return {ok:true,msg:t.optional,hint:t.url,required:false,skip:true};return {ok:validURL(s),msg:t.url,hint:t.url,required:false};
    }
    if(n==='review_url')return {ok:validGoogle(s),msg:s?t.google:t.required,hint:t.google,required:true};
    if(n==='maps_url'){
      if(!s)return {ok:true,msg:t.optional,hint:t.url,required:false,skip:true};return {ok:validURL(s),msg:t.url,hint:t.url,required:false};
    }
    if(n==='latitude'){
      if(!s)return {ok:true,msg:t.optional,hint:t.lat,required:false,skip:true};const num=Number(s);return {ok:Number.isFinite(num)&&num>=-90&&num<=90,msg:t.lat,hint:t.lat,required:false};
    }
    if(n==='longitude'){
      if(!s)return {ok:true,msg:t.optional,hint:t.lng,required:false,skip:true};const num=Number(s);return {ok:Number.isFinite(num)&&num>=-180&&num<=180,msg:t.lng,hint:t.lng,required:false};
    }
    if(n==='full_name'||n==='title')return {ok:s.length>=2&&s.length<=120,msg:s?t.name:t.required,hint:t.name,required:true};
    if(n==='start')return {ok:Boolean(s)&&Number.isFinite(new Date(s).getTime()),msg:s?t.start:t.required,hint:t.start,required:true};
    if(n==='end'){
      const st=v('start'),a=new Date(st).getTime(),b=new Date(s).getTime(),ok=Boolean(s)&&Number.isFinite(b)&&(!st||!Number.isFinite(a)||b>a);return {ok,msg:s?t.end:t.required,hint:t.end,required:true};
    }
    if(n==='company'||n==='address'||n==='location'||n==='subject'||n==='message'||n==='note'||n==='description')return {ok:s.length<=1000,msg:s.length<=1000?t.good:'Too long',hint:t.optional,required:false,skip:!s};
    return {ok:!required||Boolean(s),msg:s?t.good:t.required,hint:required?t.required:t.optional,required};
  }

  function feedbackNode(el){
    const field=el.closest('.field');if(!field)return null;
    let node=field.querySelector(':scope > .field-feedback');
    if(!node){node=document.createElement('div');node.className='field-feedback';node.id='feedback-'+el.name;node.setAttribute('aria-live','polite');field.appendChild(node);}el.setAttribute('aria-describedby',node.id);
    return node;
  }
  function paint(el,force=false){
    const field=el.closest('.field');if(!field)return;
    const r=rule(el),has=String(el.value||'').trim()!=='';
    field.classList.remove('is-valid','is-invalid','is-pending');
    const fb=feedbackNode(el);if(!fb)return;
    const reveal=force||touched.has(el)||has;
    if(r.skip&&!has){field.classList.add('is-pending');el.setAttribute('aria-invalid','false');fb.textContent=r.hint;return;}
    if(r.ok){field.classList.add('is-valid');el.setAttribute('aria-invalid','false');fb.textContent='✓ '+t.good;}
    else if(reveal){field.classList.add('is-invalid');el.setAttribute('aria-invalid','true');fb.textContent='! '+r.msg;}
    else{field.classList.add('is-pending');el.setAttribute('aria-invalid','false');fb.textContent=r.hint;}
  }

  function locationTask(){const maps=$('maps_url'),lat=$('latitude'),lng=$('longitude');if(!maps)return null;const mapOk=v('maps_url')&&rule(maps).ok,coordsOk=v('latitude')&&v('longitude')&&rule(lat).ok&&rule(lng).ok;return {ok:Boolean(mapOk||coordsOk),label:t.mapSource};}
  function tasks(){
    const names={generic:['content'],logo:['content'],wifi:['ssid'],whatsapp:['country_code','phone'],'google-review':['review_url'],vcard:['full_name'],email:['email'],sms:['phone'],phone:['phone'],event:['title','start','end']};
    if(tool==='location')return [locationTask()];
    const arr=(names[tool]||[]).map(n=>{const el=$(n),lab=el&&el.closest('.field')&&el.closest('.field').querySelector('label');return {ok:el?rule(el).ok:false,label:lab?lab.textContent.trim():n};});
    if(tool==='wifi'&&v('security')!=='nopass'){const el=$('password'),lab=el&&el.closest('.field')&&el.closest('.field').querySelector('label');arr.push({ok:el?rule(el).ok:false,label:lab?lab.textContent.trim():'Password'});}
    return arr.filter(Boolean);
  }
  let progress=form.querySelector('.form-readiness');
  if(!progress){progress=document.createElement('section');progress.className='form-readiness';progress.setAttribute('aria-live','polite');progress.innerHTML='<div class="readiness-top"><strong></strong><span></span></div><div class="readiness-track"><i></i></div><div class="readiness-missing"></div>';form.insertBefore(progress,form.firstChild);}
  function updateProgress(){
    const list=tasks(),total=list.length||1,ready=list.filter(x=>x&&x.ok).length,pct=Math.round(ready/total*100),missing=list.filter(x=>x&&!x.ok).map(x=>x.label);
    progress.classList.toggle('is-complete',ready===total);
    progress.querySelector('strong').textContent=`${ready}/${total} ${t.ready}`;
    progress.querySelector('.readiness-top span').textContent=`${pct}%`;
    progress.querySelector('.readiness-track i').style.width=pct+'%';
    progress.querySelector('.readiness-missing').textContent=missing.length?`${t.left}: ${missing.join(' · ')}`:t.complete;
  }
  function syncConditionalFields(){
    if(tool==='wifi'&&$('password')&&$('security')){const off=v('security')==='nopass',pass=$('password');pass.disabled=off;const field=pass.closest('.field');if(field)field.classList.toggle('is-disabled',off);}
  }
  function refresh(force=false){syncConditionalFields();contentControls.forEach(el=>paint(el,force));updateProgress();}
  contentControls.forEach(el=>{
    el.addEventListener('blur',()=>{if(el.name==='country_code'){const normalized=normalizeCountryCode(el.value);if(normalized)el.value=normalized;}touched.add(el);refresh(false)});
    el.addEventListener('input',()=>refresh(false));
    el.addEventListener('change',()=>{touched.add(el);refresh(false)});
  });
  form.addEventListener('submit',e=>{e.preventDefault();contentControls.forEach(el=>touched.add(el));refresh(true);const bad=form.querySelector('.field.is-invalid input,.field.is-invalid textarea,.field.is-invalid select');if(bad)bad.focus({preventScroll:false});});
  refresh(false);
  window.FastooleeFormUX={refresh,valid:()=>tasks().every(x=>x&&x.ok)};
})();
